r_id ||\\n      chatMessage.userId ||\\n      sessionId ||\\n      'n8n-chat-user';\\n  }\\n\\n  const jsonImages = Array.isArray(item.json.images) ? item.json.images : [];\\n\\n  if (jsonImages.length > 0) {\\n    totalAttachments += item.json.total_attachments || jsonImages.length;\\n\\n    for (const img of jsonImages) {\\n      if (!img || !img.image_base64) {\\n        continue;\\n      }\\n\\n      images.push({\\n        image_base64: img.image_base64,\\n        mime_type: img.mime_type || 'image/png',\\n        file_name: img.file_name || `image_${images.length + 1}.png`,\\n        binary_key: img.binary_key || '',\\n        image_index: images.length\\n      });\\n    }\\n\\n    continue;\\n  }\\n\\n  const binaryData = item.binary || {};\\n  const binaryKeys = Object.keys(binaryData);\\n\\n  totalAttachments += binaryKeys.length;\\n\\n  for (const binaryKey of binaryKeys) {\\n    const binaryFile = binaryData[binaryKey];\\n    const mimeType = String(binaryFile?.mimeType || '').toLowerCase();\\n\\n    if (!mimeType.startsWith('image/')) {\\n      continue;\\n    }\\n\\n    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, binaryKey);\\n\\n    images.push({\\n      image_base64: buffer.toString('base64'),\\n      mime_type: binaryFile.mimeType || 'image/png',\\n      file_name: binaryFile.fileName || `image_${images.length + 1}.png`,\\n      binary_key: binaryKey,\\n      image_index: images.length\\n    });\\n  }\\n}\\n\\nconst hasImage = images.length > 0;\\n\\nreturn [\\n  {\\n    json: {\\n      message: userMessage,\\n      user_id: userId,\\n      session_id: sessionId,\\n      conversation_id: sessionId,\\n\\n      has_attachment: totalAttachments > 0 || hasImage,\\n      has_image: hasImage,\\n\\n      total_attachments: totalAttachments > 0 ? totalAttachments : images.length,\\n      total_images: images.length,\\n\\n      images,\\n\\n      skip_ocr: !hasImage,\\n      reason: !hasImage\\n        ? 'Nenhuma imagem foi encontrada em 