PI Chat	f	[{"parameters":{"jsCode":"const items = $input.all();\\n\\nlet userMessage = '';\\nlet sessionId = '';\\nconst images = [];\\n\\nfor (let itemIndex = 0; itemIndex < items.length; itemIndex++) {\\n  const item = items[itemIndex];\\n\\n  const chatMessage = item.json.chatMessage || {};\\n\\n  if (!userMessage) {\\n    userMessage =\\n      chatMessage.chatInput ||\\n      chatMessage.text ||\\n      chatMessage.message ||\\n      item.json.chatInput ||\\n      item.json.message ||\\n      '';\\n  }\\n\\n  if (!sessionId) {\\n    sessionId =\\n      chatMessage.sessionId ||\\n      item.json.sessionId ||\\n      item.json.conversation_id ||\\n      item.json.user_id ||\\n      '';\\n  }\\n\\n  const binaryData = item.binary || {};\\n  const binaryKeys = Object.keys(binaryData);\\n\\n  for (const binaryKey of binaryKeys) {\\n    const file = binaryData[binaryKey];\\n\\n    const mimeType = String(file?.mimeType || '').toLowerCase();\\n\\n    if (!mimeType.startsWith('image/')) {\\n      continue;\\n    }\\n\\n    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, binaryKey);\\n\\n    images.push({\\n      image_base64: buffer.toString('base64'),\\n      mime_type: file.mimeType || 'image/png',\\n      file_name: file.fileName || `image_${images.length + 1}.png`,\\n      binary_key: binaryKey,\\n      image_index: images.length\\n    });\\n  }\\n}\\n\\nreturn [\\n  {\\n    json: {\\n      message: userMessage,\\n      user_id: sessionId || 'n8n-chat',\\n      session_id: sessionId,\\n\\n      has_image: images.length > 0,\\n      total_images: images.length,\\n\\n      images,\\n\\n      skip_ocr: images.length === 0,\\n      reason: images.length === 0\\n        ? 'Nenhuma imagem encontrada no $binary do Chat Trigger.'\\n        : null\\n    }\\n  }\\n];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-2080,1952],"id":"a0608e8d-cc90-4ae2-aff0-83296a55851f","name":"ImageValidator"},{"parameters":{"method":"POST","url":"http://10.247.179.197:8012/chat","sendBody":true,"specifyBody":"json","jsonBody":"={{ $json }}","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"position":[-1408,1952],"id":"1fe57960-a3c5-482a-b5b6-c01b9384ac9c","name":"AgentPiChat"},{"parameters":{"public":true,"initialMessages":"Olá! 👋\\nEu sou PI Chat, assistente do PIMS!","options":{"allowFileUploads":true,"subtitle":"","title":"PI Chat 🤖"}},"type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.4,"position":[-2304,1952],"id":"53758d0c-6f5e-4d3b-a408-30dc4edaa97a","name":"chatMessage","webhookId":"9123cba4-b04f-4b35-818e-dbf7a301831f"},{"parameters":{"jsCode":"const items = $input.all();\\n\\nlet userMessage = '';\\nlet sessionId = '';\\nlet userId = '';\\n\\nconst images = [];\\nlet totalAttachments = 0;\\n\\nfor (let itemIndex = 0; itemIndex < items.length; itemIndex++) {\\n  const item = items[itemIndex];\\n  const chatMessage = item.json.chatMessage || {};\\n\\n  if (!userMessage) {\\n    userMessage =\\n      item.json.message ||\\n      item.json.user_message ||\\n      chatMessage.chatInput ||\\n      chatMessage.text ||\\n      chatMessage.message ||\\n      item.json.chatInput ||\\n      item.json.text ||\\n      '';\\n  }\\n\\n  if (!sessionId) {\\n    sessionId =\\n      item.json.session_id ||\\n      item.json.sessionId ||\\n      item.json.conversation_id ||\\n      chatMessage.sessionId ||\\n      '';\\n  }\\n\\n  if (!userId) {\\n    userId =\\n      item.json.user_id ||\\n      chatMessage.userId ||\\n      sessionId ||\\n      'n8n-chat-user';\\n  }\\n\\n  const jsonImages = Array.isArray(item.json.images) ? item.json.images : [];\\n\\n  if (jsonImages.length > 0) {\\n    totalAttachments += item.json.total_attachments || jsonImages.length;\\n\\n    for (const img of jsonImages) {\\n      if (!img || !img.image_base64) {\\n        continue;\\n      }\\n\\n      images.push({\\n        image_base64: img.image_base64,\\n        mime_type: img.mime_type || 'image/png',\\n        file_name: img.file_name || `image_${images.length + 1}.png`,\\n        binary_key: img.binary_key || '',\\n        image_index: images.length\\n      });\\n    }\\n\\n    continue;\\n  }\\n\\n  const binaryData = item.binary || {};\\n  const binaryKeys = Object.keys(binaryData);\\n\\n  totalAttachments += binaryKeys.length;\\n\\n  for (const binaryKey of binaryKeys) {\\n    const binaryFile = binaryData[binaryKey];\\n    const mimeType = String(binaryFile?.mimeType || '').toLowerCase();\\n\\n    if (!mimeType.startsWith('image/')) {\\n      continue;\\n    }\\n\\n    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, binaryKey);\\n\\n    images.push({\\n      image_base64: buffer.toString('base64'),\\n      mime_type: binaryFile.mimeType || 'image/png',\\n      file_name: binaryFile.fileName || `image_${images.length + 1}.png`,\\n      binary_key: binaryKey,\\n      image_index: images.length\\n    });\\n  }\\n}\\n\\nconst hasImage = images.length > 0;\\n\\nreturn [\\n  {\\n    json: {\\n      message: userMessage,\\n      user_id: userId,\\n      session_id: sessionId,\\n      conversation_id: sessionId,\\n\\n      has_attachment: totalAttachments > 0 || hasImage,\\n      has_image: hasImage,\\n\\n      total_attachments: totalAttachments > 0 ? totalAttachments : images.length,\\n      total_images: images.length,\\n\\n      images,\\n\\n      skip_ocr: !hasImage,\\n      reason: !hasImage\\n        ? 'Nenhuma imagem foi encontrada em json.images nem em binary.'\\n        : null\\n    }\\n  }\\n];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-1632,2032],"id":"3bbe6ee5-a537-4f08-86e6-1e7ceaa9e504","name":"PrepareData"},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const body = $json.body ?? $json;\\n\\nconst answer =\\n  body.answer ??\\n  body.output ??\\n  body.response ??\\n  body.text ??\\n  '';\\n\\nconst attachments = Array.isArray(body.attachments)\\n  ? body.attachments\\n  : [];\\n\\nreturn {\\n  json: {\\n    ...body,\\n    answer,\\n    output: answer,\\n    attachments,\\n    hasAttachments: attachments.length > 0,\\n  },\\n};"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-1184,1952],"id":"d557509f-aec3-46b5-b7cb-464cf3fe75d0","name":"NormalizeAgentResponse"},{"parameters":{"rules":{"values":[{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"leftValue":"={{ $json.hasAttachments }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true},"id":"1d08cb34-caed-49ce-98f1-22da58881e82"}],"combinator":"and"},"renameOutput":true,"outputKey":"True"},{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"2713cbf5-d39f-4b07-9d2a-1428532f4429","leftValue":"={{ $json.hasAttachments }}","rightValue":"","operator":{"type":"boolean","operation":"false","singleValue":true}}],"combinator":"and"},"renameOutput":true,"outputKey":"False"}]},"options":{}},"type":"n8n-nodes-base.switch","typeVersion":3.4,"position":[-960,1952],"id":"88ced77b-875c-4868-b9f7-f986d1867452","name":"HasAttachments"},{"parameters":{"rules":{"values":[{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"leftValue":"={{ $json.has_image }}","rightValue":"does_not","operator":{"type":"boolean","operation":"false","singleValue":true},"id":"50538d12-cd2c-4ace-8ff4-b9285047d35c"}],"combinator":"and"},"renameOutput":true,"outputKey":"does_not"},{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":3},"conditions":[{"id":"0f4b1ef1-36db-425d-9258-a95a09ba8eed","leftValue":"={{ $json.has_image }}","rightValue":"has_image","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"renameOutput":true,"outputKey":"has_image"}]},"options":{}},"type":"n8n-nodes-base.switch","typeVersion":3.4,"position":[-1856,1952],"id":"d9a752de-0d9a-45f3-918d-b72398cd1003","name":"HasImages"},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const answer =\\n  $json.answer ??\\n  $json.output ??\\n  $json.response ??\\n  $json.text ??\\n  '';\\n\\nreturn {\\n  json: {\\n    output: answer,\\n  },\\n};"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-736,2048],"id":"10b26b64-3c68-4e7d-bca8-bf59d7f41fdb","name":"ReturnTextOnly"},{"parameters":{"jsCode":"const input = $input.first().json;\\n\\nconst apiBaseUrl = 'http://10.247.179.197:8012'; // use a mesma base do AgentPiChat, sem /chat\\n\\nconst answer =\\n  input.answer ??\\n  input.output ??\\n  input.response ??\\n  input.text ??\\n  '';\\n\\nconst attachments = Array.isArray(input.attachments)\\n  ? input.attachments\\n  : [];\\n\\nreturn attachments.map((att, index) => {\\n  const downloadUrl = att.download_url || '';\\n\\n  const fullDownloadUrl = downloadUrl.startsWith('http')\\n    ? downloadUrl\\n    : apiBaseUrl.replace(/\\\\/$/, '') + downloadUrl;\\n\\n  return {\\n    json: {\\n      answer,\\n      output: answer,\\n      index,\\n      total: attachments.length,\\n      artifact_id: att.artifact_id,\\n      filename: att.filename || `artifact_${index + 1}`,\\n      mime_type: att.mime_type || 'application/octet-stream',\\n      size_bytes: att.size_bytes,\\n      download_url: downloadUrl,\\n      full_download_url: fullDownloadUrl,\\n    },\\n  };\\n});"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-736,1856],"id":"8bdf241a-6c5f-4f80-a0ef-c7472cb15b20","name":"PrepareAttachmentDownload"},{"parameters":{"url":"={{ $json.full_download_url }}","sendHeaders":true,"headerParameters":{"parameters":[{"name":"X-Agent-Token","value":"ldbgDXu8F95wVzl85vNrv7Y63gm5A7c6Xa7Ky32PKIoZPdGW-WvfFUDpiPHVB_4-"}]},"options":{"response":{"response":{"responseFormat":"file"}}}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"position":[-512,1856],"id":"cd95a5a3-fdc2-411a-bc03-961bf6cf5a4c","name":"DownloadArtifact"},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const filename = $json.filename || 'arquivo';\\n\\nconst answer =\\n  $json.answer ??\\n  $json.output ??\\n  $json.response ??\\n  $json.text ??\\n  'Arquivo gerado.';\\n\\nreturn {\\n  json: {\\n    output: `${answer}\\\\n\\\\nArquivo baixado pelo n8n: ${filename}`,\\n    filename,\\n    mime_type: $json.mime_type,\\n  },\\n  binary: $binary,\\n};"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-288,1856],"id":"892a3123-b0a2-47fe-b382-ece1ba7fd231","name":"ReturnTextWithDownloadedFile"}]	{"ImageValidator":{"main":[[{"node":"HasImages","type":"main","index":0}]]},"AgentPiChat":{"main":[[{"node":"NormalizeAgentResponse","type":"main","index":0}]]},"chatMessage":{"main":[[{"node":"ImageValidator","type":"main","index":0}]]},"PrepareData":{"main":[[{"node":"AgentPiChat","type":"main","index":0}]]},"NormalizeAgentResponse":{"main":[[{"node":"HasAttachments","type":"main","index":0}]]},"HasImages":{"main":[[{"node":"AgentPiChat","type":"main","index":0}],[{"node":"PrepareData","type":"main","index":0}]]},"HasAttachments":{"main":[[{"node":"PrepareAttachmentDownload","type":"main","index":0}],[{"node":"ReturnTextOnly","type":"main","index":0}]]},"PrepareAttachmentDownload":{"main":[[{"node":"DownloadArtifact","type":"main","index":0}]]},"DownloadArtifact":{"main":[[{"node":"ReturnTextWithDownloadedFile","type":"main","index":0}]]}}	2026-04-13 13:56:31.627+00	2026-07-28 16:42:46.451+00	{"executionOrder":"v1","binaryMode":"separate"}	\N	{}	77ca95c4-8a86-436e-96c0-b8d2b0081bb8	1	cNyiTlYdWqC0kuUq	{"templateCredsSetupCompleted":true}	\N	f	4862	\N	\N	[]
