ttachment = attachments.length > 0;\\n\\nconst items = $input.all();\\n\\nconst userMessage =\\n  message.argumentText ||\\n  items[0]?.json?.user_message ||\\n  '';\\n\\nconst images = [];\\n\\nfor (let i = 0; i < items.length; i++) {\\n  const item = items[i];\\n\\n  const currentAttachment = item.json.attachment || null;\\n  const binaryData = item.binary || {};\\n  const binaryFieldName = Object.keys(binaryData)[0] || '';\\n\\n  if (!binaryFieldName) {\\n    continue;\\n  }\\n\\n  const binaryFile = binaryData[binaryFieldName];\\n\\n  const mimeType =\\n    currentAttachment?.contentType ||\\n    binaryFile?.mimeType ||\\n    item.json.attachment_content_type ||\\n    'image/png';\\n\\n  const fileName =\\n    binaryFile?.fileName ||\\n    currentAttachment?.contentName ||\\n    item.json.attachment_name ||\\n    '';\\n\\n  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryFieldName);\\n  const imageBase64 = buffer.toString('base64');\\n\\n  if (!imageBase64) {\\n    continue;\\n  }\\n\\n  images.push({\\n    image_base64: imageBase64,\\n    mime_type: mimeType,\\n    file_name: fileName,\\n    image_index: item.json.image_index ?? i\\n  });\\n}\\n\\nreturn [\\n  {\\n    json: {\\n      message: userMessage,\\n      user_id:\\n        payload.user?.name ||\\n        message.sender?.name ||\\n        message.sender?.email ||\\n        '',\\n\\n      has_attachment: hasAttachment,\\n      has_image: images.length > 0,\\n      total_attachments: attachments.length,\\n      total_images: images.length,\\n\\n      images,\\n\\n      skip_ocr: images.length === 0,\\n      reason: images.length === 0\\n        ? 'Nenhum binário de imagem foi encontrado.'\\n        : null\\n    }\\n  }\\n];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-1360,1936],"id":"d40a6fea-4011-4cef-a8cf-1f9ff1d91f8a","name":"BinaryParsing"},{"parameters":{"jsCode":"// Pega o payload do Google Chat vindo do Pub/Sub\\nconst payload = $('GCP Pub/Sub Subscriber').first().json.data?.chat?.messagePayload || {};\\nconst message = payload.message || {};\\n\\n// Texto da mensagem, se existir\\nconst userMessage = message.argumentText || '';\\n\\n// Lista de anexos\\nconst attachments = Array.isArray(message.attachment) ? message.attachment : [];\\n\\n// Filtra apenas anexos de imagem\\nconst imageAttachments = attachments.filter(att =>\\n  typeof att?.contentType === 'string' &&\\n  att.contentType.toLowerCase().startsWith('image/')\\n);\\n\\n// Flags gerais\\nconst hasAttachment = attachments.length > 0;\\nconst hasImage = imageAttachments.length > 0;\\n\\n// Se não houver imagem, ainda retorna 1 item para o fluxo não quebrar\\nif (!hasImage) {\\n  return [\\n    {\\n      json: {\\n        user_message: userMessage,\\n        has_attachment: hasAttachment,\\n        has_image: false,\\n        total_attachments: attachments.length,\\n        total_images: 0,\\n        attachment: null,\\n        attachment_resource_name: '',\\n        attachment_name: '',\\n        attachment_content_type: '',\\n        attachment_download_uri: '',\\n        attachment_thumbnail_uri: '',\\n        image_attachments: []\\n      }\\n    }\\n  ];\\n}\\n\\n// Retorna 1 item por imagem\\nreturn imageAttachments.map((image, index) => ({\\n  json: {\\n    user_message: userMessage,\\n    has_attachment: hasAttachment,\\n    has_image: true,\\n    total_attachments: attachments.length,\\n    total_images: imageAttachments.length,\\n    image_index: index,\\n\\n    // imagem atual\\n    attachment: image,\\n\\n    // campos úteis já extraídos\\n    attachment_resource_name: image?.attachmentDataRef?.resourceName || '',\\n    attachment_name: image?.contentName || '',\\n    attachment_content_type: image?.contentType || '',\\n    attachment_download_uri: image?.downloadUri || '',\\n    attachment_thumbnail_uri: image?.thumbnailUri || '',\\n\\n    // lista completa, caso queira usar depois\\n    image_attachments: imageAttachments\\n  }\\n}));"},"type":"n8n-nodes-ba