ex, binaryKey);\\n\\n    images.push({\\n      image_base64: buffer.toString('base64'),\\n      mime_type: file.mimeType || 'image/png',\\n      file_name: file.fileName || `image_${images.length + 1}.png`,\\n      binary_key: binaryKey,\\n      image_index: images.length\\n    });\\n  }\\n}\\n\\nreturn [\\n  {\\n    json: {\\n      message: userMessage,\\n      user_id: sessionId || 'n8n-chat',\\n      session_id: sessionId,\\n\\n      has_image: images.length > 0,\\n      total_images: images.length,\\n\\n      images,\\n\\n      skip_ocr: images.length === 0,\\n      reason: images.length === 0\\n        ? 'Nenhuma imagem encontrada no $binary do Chat Trigger.'\\n        : null\\n    }\\n  }\\n];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-2080,1856],"id":"63061344-6422-4c1e-be6c-c9182c42c5f2","name":"ImageValidator"},{"parameters":{"method":"POST","url":"http://10.247.179.197:8003/chat","sendBody":true,"specifyBody":"json","jsonBody":"={{ $json }}","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"position":[-1408,1856],"id":"ab2a3ff5-f5e2-40a7-99ae-e578501c5b68","name":"AgentPiChat"},{"parameters":{"public":true,"initialMessages":"Olá! 👋\\nEu sou PI Chat, assistente do PIMS!","options":{"allowFileUploads":true,"subtitle":"","title":"PI Chat 🤖"}},"type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.4,"position":[-2304,1856],"id":"224a1225-8e2b-4554-9c19-d1f62f9167dd","name":"chatMessage","webhookId":"1206b694-e9d1-4ac9-8d69-e83dec834d8d"},{"parameters":{"jsCode":"const items = $input.all();\\n\\nlet userMessage = '';\\nlet sessionId = '';\\nlet userId = '';\\n\\nconst images = [];\\nlet totalAttachments = 0;\\n\\nfor (let itemIndex = 0; itemIndex < items.length; itemIndex++) {\\n  const item = items[itemIndex];\\n  const chatMessage = item.json.chatMessage || {};\\n\\n  if (!userMessage) {\\n    userMessage =\\n      item.json.message ||\\n      item.json.user_message ||\\n      chatMessage.chatInput ||\\n      chatMessage.text ||\\n      chatMessage.message ||\\n      item.json.chatInput ||\\n      item.json.text ||\\n      '';\\n  }\\n\\n  if (!sessionId) {\\n    sessionId =\\n      item.json.session_id ||\\n      item.json.sessionId ||\\n      item.json.conversation_id ||\\n      chatMessage.sessionId ||\\n      '';\\n  }\\n\\n  if (!userId) {\\n    userId =\\n      item.json.user_id ||\\n      chatMessage.userId ||\\n      sessionId ||\\n      'n8n-chat-user';\\n  }\\n\\n  const jsonImages = Array.isArray(item.json.images) ? item.json.images : [];\\n\\n  if (jsonImages.length > 0) {\\n    totalAttachments += item.json.total_attachments || jsonImages.length;\\n\\n    for (const img of jsonImages) {\\n      if (!img || !img.image_base64) {\\n        continue;\\n      }\\n\\n      images.push({\\n        image_base64: img.image_base64,\\n        mime_type: img.mime_type || 'image/png',\\n        file_name: img.file_name || `image_${images.length + 1}.png`,\\n        binary_key: img.binary_key || '',\\n        image_index: images.length\\n      });\\n    }\\n\\n    continue;\\n  }\\n\\n  const binaryData = item.binary || {};\\n  const binaryKeys = Object.keys(binaryData);\\n\\n  totalAttachments += binaryKeys.length;\\n\\n  for (const binaryKey of binaryKeys) {\\n    const binaryFile = binaryData[binaryKey];\\n    const mimeType = String(binaryFile?.mimeType || '').toLowerCase();\\n\\n    if (!mimeType.startsWith('image/')) {\\n      continue;\\n    }\\n\\n    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, binaryKey);\\n\\n    images.push({\\n      image_base64: buffer.toString('base64'),\\n      mime_type: binaryFile.mimeType || 'image/png',\\n      file_name: binaryFile.fileName || `image_${images.length + 1}.png`,\\n      binary_key: binaryKey,\\n      image_index: images.length\\n    });\\n  }\\n}\\n\\nconst hasImage = images.length > 0;\\n\\nreturn [\\n  {\\n    json: {\\n      message: userMessage,\\n      user_id: userId,\\n      session_id: sessionId,\\n      conversation_id: sessionId,\\n\\n      has_attachment: totalAttachments > 0 || hasImage,\\n      has_image: hasImage,\\n\\n      total_attachments: totalAttachments > 0 ? totalAttachments : images.length,\\n      total_images: images.length,\\n\\n      images,\\n\\n      skip_ocr: !hasImage,\\n      reason: !hasImage\\n        ? 'Nenhuma imagem foi encontrada em json.images nem em binary.'\\n        : null\\n    }\\n  }\\n];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[-1632,1936],"id":"efd6e619-d82f-41e3-b328-3bd70f8e8c0b","name":"PrepareData"}]	{"Switch":{"main":[[{"node":"AgentPiChat","type":"main","index":0}],[{"node":"PrepareData","type":"main","index":0}]]},"ImageValidator":{"main":[[{"node":"Switch","type":"main","index":0}]]},"AgentPiChat":{"main":[[]]},"chatMessage":{"main":[[{"node":"ImageValidator","type":"main","index":0}]]},"PrepareData":{"main":[[{"node":"AgentPiChat","type":"main","index":0}]]}}	2026-06-09 13:54:56.062+00	2026-06-10 15:31:51.285+00	{"executionOrder":"v1","binaryMode":"separate","availableInMCP":false}	\N	{}	8fe31aef-ea1b-454a-89bd-ee37530a1a89	0	ZkllK8NX1BRvDXio	{"templateCredsSetupCompleted":true}	\N	f	3	\N	\N	[]
