ts","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify($json.calculator_body) }}","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"position":[3984,3000],"id":"cfd6c66f-fa4f-4856-8043-e4c1db4443a0","name":"MathStatistics","onError":"continueErrorOutput"},{"parameters":{"method":"POST","url":"http://math_tool:8001/calculus","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify($json.calculator_body) }}","options":{}},"type":"n8n-nodes-base.httpRequest","typeVersion":4.4,"position":[3984,3192],"id":"0824b803-cbac-4d07-bb83-e2b4b233a390","name":"MathCalculus","onError":"continueErrorOutput"},{"parameters":{"operation":"update","messageId":"={{ $('Create a message').item.json.name }}","updateFieldsUi":{"text":"={{ $json.message.content }}"}},"type":"n8n-nodes-base.googleChat","typeVersion":1,"position":[4656,3016],"id":"2220ce0c-5a2f-4093-b930-f59be259e25f","name":"HappyEnd5","webhookId":"7ac8f4f3-412e-4251-bf80-dc79f81b5ebf","credentials":{"googleApi":{"id":"41NSe9ob4JUhVVTF","name":"Chat account"}}},{"parameters":{"jsCode":"const modelLocal = 'gemma4:e4b';\\nconst modelFallback = 'nvidia/nemotron-nano-9b-v2:free';\\n\\n// Pergunta original do usuário\\nconst userPrompt =\\n  $('PromptsRewriter').first().json.user_message_original || \\"\\";\\n\\n// Resultado vindo da calculadora\\nconst calculatorResult = $input.first().json.result || $input.first().json;\\n\\n// Dados do validator\\nconst validator = $('QueryValidator1').first().json;\\n\\nconst operation = validator.operation || null;\\nconst tagAtual = validator.tag || validator.tags?.[0] || null;\\nconst tags = validator.tags || (tagAtual ? [tagAtual] : []);\\n\\n// Resposta da PI Web API\\nconst piBatchResponse = $('PI Web API1').first().json;\\n\\n// Monta unidade por tag\\nconst unidadesPorTag = {};\\n\\ntags.forEach((tag, index) => {\\n  const pointData = piBatchResponse[`point_${index}`];\\n  const content = pointData?.Content || pointData?.content || {};\\n\\n  const nomeTag = content.Name || tag;\\n  const unidade = content.EngineeringUnits || content.engineeringUnits || null;\\n\\n  unidadesPorTag[nomeTag] = unidade;\\n});\\n\\n// Unidade da tag atual\\nconst engUnit = tagAtual ? unidadesPorTag[tagAtual] : null;\\n\\nfunction inferirUnidadeResultado(operation, engUnit, calculatorResult) {\\n  if (!engUnit) {\\n    return null;\\n  }\\n\\n  const timeUnit = calculatorResult.time_unit || calculatorResult.result?.time_unit || null;\\n\\n  if (operation === \\"integral\\") {\\n    if (engUnit === \\"kW\\" && timeUnit === \\"hour\\") {\\n      return \\"kWh\\";\\n    }\\n\\n    if ((engUnit === \\"Nm³/h\\" || engUnit === \\"m³/h\\" || engUnit === \\"m3/h\\") && timeUnit === \\"hour\\") {\\n      return engUnit.replace(\\"/h\\", \\"\\");\\n    }\\n\\n    if ((engUnit === \\"L/min\\" || engUnit === \\"l/min\\") && timeUnit === \\"minute\\") {\\n      return engUnit.replace(\\"/min\\", \\"\\");\\n    }\\n\\n    if ((engUnit === \\"m/min\\") && timeUnit === \\"minute\\") {\\n      return \\"m\\";\\n    }\\n\\n    if ((engUnit === \\"kg/h\\" || engUnit === \\"t/h\\") && timeUnit === \\"hour\\") {\\n      return engUnit.replace(\\"/h\\", \\"\\");\\n    }\\n\\n    return `${engUnit} integrada no tempo`;\\n  }\\n\\n  if (operation === \\"derivative\\") {\\n    if (timeUnit) {\\n      return `${engUnit}/${timeUnit}`;\\n    }\\n\\n    return `${engUnit}/tempo`;\\n  }\\n\\n  return engUnit;\\n}\\n\\nconst unidadeResultado = inferirUnidadeResultado(operation, engUnit, calculatorResult);\\n\\nconst promptFinal = `\\nVocê deve responder ao usuário com base no resultado da calculadora.\\n\\nInstruções:\\n- Não invente valores.\\n- Responda em português, de forma curta e clara.\\n- Se o resultado tiver muitas casas decimais, arredonde para no máximo 2 casas.\\n- Responda exatamente o que o usuário perguntou.\\n- Use a unidade do resultado quando ela estiver disponível.\\n- Não mostre JSON.\\n- Não cite n8n, API ou ferramenta interna.\\n\\nPergunta do usuário:\\n${userPrompt}\\n\\nTag principal:\\n${tagAtual || \\"não informada\\"}\\n\\nUnidade de engenharia da tag principal:\\n${engUnit || \\"não informada\\"}\\n\\nUnidade provável do resultado:\\n${unidadeResultado || \\"não informada\\"}\\n\\nUnidades por tag:\\n${JSON.stringify(unidadesPorTag, null, 2)}\\n\\nOperação:\\n${operation}\\n\\nResultado da calculadora:\\n${JSON.stringify(calculatorResult, null, 2)}\\n\\nRegras de interpretação:\\n- Se a operação for integral de potência em kW no tempo em horas, o resultado é energia acumulada em kWh.\\n- Se a operação for integral de vazão em m³/h ou Nm³/h no tempo em horas, o resultado é volume acumulado em m³ ou Nm³.\\n- Se a operação for integral de velocidade em m/min no tempo em minutos, o resultado é comprimento acumulado em metros.\\n- Se a operação for derivada, o resultado é taxa de variação da unidade da tag por tempo.\\n- Se a unidade não puder ser inferida com segurança, responda sem unidade.\\n\\nAgora responda ao usuário.\\n`.trim();\\n\\nreturn [\\n  {\\n    json: {\\n      model: modelLocal,\\n      model_local: modelLocal,\\n      model_fallback: modelFallback,\\n      userPrompt,\\n      tagAtual,\\n      engUnit,\\n      unidades_por_tag: unidadesPorTag,\\n      unidade_resultado: unidadeResultado,\\n      calculator_result: calculatorResult,\\n      promptFinal,\\n      messages: [\\n        {\\n          role: 'user',\\n          content: promptFinal\\n        }\\n      ],\\n      request_local: {\\n        model: modelLocal,\\n        messages: [\\n          {\\n            role: 'user',\\n            content: promptFinal\\n          }\\n        ],\\n        stream: false\\n      },\\n      request_fallback: {\\n        model: modelFallback,\\n        messages: [\\n          {\\n            role: 'user',\\n            content: promptFinal\\n          }\\n        ]\\n      }\\n    }\\n  }\\n];"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[4208,3016],"id":"3ca6e2aa-09d5